use std::fs

fn main() {
    let n = 200000
    let mut sieve: Vec<bool> = []
    for i in 0..(n + 1) { sieve.push(true) }
    let mut counts: Vec<int> = []
    let mut largest: Vec<int> = []
    let mut c = 0
    let mut last = 0
    for i in 0..(n + 1) {
        if i >= 2 && sieve[i] {
            c += 1
            last = i as int
            let ii: int = i as int
            let mut j: int = ii * ii
            while j <= n {
                sieve[j] = false
                j += ii
            }
        }
        counts.push(c)
        largest.push(last)
    }
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    for line in text.lines() {
        if first {
            first = false
            continue
        }
        let t = line.trim()
        if t.len() == 0 { continue }
        let v: int = t.parse::<int>().unwrap_or(0)
        if counts[v] == 0 {
            println("0 none")
        } else {
            println("${counts[v]} ${largest[v]}")
        }
    }
}

